+  <script>
+    function App() {
+      return `
+        <main id="maincontent" class="page-shell" tabindex="-1">
+          <section class="hero" aria-labelledby="support-heading">
+            <div>
+              <div class="eyebrow">Support team</div>
+              <h1 id="support-heading">Get in touch with product support</h1>
+              <p>
+                Share your details and our team will follow up with setup guidance,
+                account help, or product troubleshooting.
+              </p>
+              <ul class="hero-points" aria-label="Support benefits">
+                <li>
+                  <span class="point-icon" aria-hidden="true">1</span>
+                  <div>
+                    <strong>Fast human follow-up</strong>
+                    <span>Reach the right team without routing through a generic inbox.</span>
+                  </div>
+                </li>
+                <li>
+                  <span class="point-icon" aria-hidden="true">2</span>
+                  <div>
+                    <strong>Clear next steps</strong>
+                    <span>We use your contact details to coordinate the best response.</span>
+                  </div>
+                </li>
+              </ul>
+            </div>
+            ${ContactForm()}
+          </section>
+        </main>
+      `;
+    }
+
+    function ContactForm() {
+      return `
+        <section class="form-card" aria-labelledby="contact-form-heading">
+          <h2 id="contact-form-heading">Contact support</h2>
+          <p>Required fields are marked with an asterisk.</p>
+          <form id="support-form" class="contact-form" novalidate>
+            <p class="required-note">Fields marked <span class="required-mark" aria-hidden="true">*</span> are required.</p>
+
+            <div class="form-field" data-field="fullName">
+              <label for="fullName">Full name <span class="required-mark" aria-hidden="true">*</span></label>
+              <input
+                id="fullName"
+                name="fullName"
+                type="text"
+                autocomplete="name"
+                required
+                aria-required="true"
+                aria-describedby="fullName-error"
+              >
+              <p id="fullName-error" class="error-text" hidden></p>
+            </div>
+
+            <div class="form-field" data-field="email">
+              <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
+              <input
+                id="email"
+                name="email"
+                type="email"
+                inputmode="email"
+                autocomplete="email"
+                required
+                aria-required="true"
+                aria-describedby="email-error"
+              >
+              <p id="email-error" class="error-text" hidden></p>
+            </div>
+
+            <div class="form-field" data-field="phone">
+              <label for="phone">Phone number</label>
+              <input
+                id="phone"
+                name="phone"
+                type="tel"
+                inputmode="tel"
+                autocomplete="tel"
+                aria-describedby="phone-help phone-error"
+              >
+              <p id="phone-help" class="helper-text">Optional. Use digits only, such as 5551234567, or include spaces, dashes, or a leading + for country code.</p>
+              <p id="phone-error" class="error-text" hidden></p>
+            </div>
+
+            <p id="form-status" class="status-text" aria-live="polite"></p>
+            <button type="submit">Send request</button>
+          </form>
+        </section>
+      `;
+    }
+
+    function render() {
+      document.getElementById("app").innerHTML = App();
+      setupForm();
+    }
+
+    function setupForm() {
+      const form = document.getElementById("support-form");
+      const fields = {
+        fullName: {
+          input: document.getElementById("fullName"),
+          error: document.getElementById("fullName-error"),
+          validate(value) {
+            if (!value.trim()) {
+              return "Error: Enter your full name.";
+            }
+            return "";
+          }
+        },
+        email: {
+          input: document.getElementById("email"),
+          error: document.getElementById("email-error"),
+          validate(value) {
+            if (!value.trim()) {
+              return "Error: Enter your email address.";
+            }
+            if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(value.trim())) {
+              return "Error: Enter a valid email address, like name@example.com.";
+            }
+            return "";
+          }
+        },
+        phone: {
+          input: document.getElementById("phone"),
+          error: document.getElementById("phone-error"),
+          validate(value) {
+            if (!value.trim()) {
+              return "";
+            }
+            if (!/^\\+?[0-9()\\-\\s]{7,20}$/.test(value.trim())) {
+              return "Error: Enter a valid phone number using digits and optional spaces, dashes, parentheses, or a leading +.";
+            }
+            return "";
+          }
+        }
+      };
+      const status = document.getElementById("form-status");
+      let submitted = false;
+
+      function setFieldState(name, message) {
+        const { input, error } = fields[name];
+        const container = input.closest(".form-field");
+        const showError = Boolean(message) && submitted;
+
+        input.setAttribute("aria-invalid", showError ? "true" : "false");
+        error.textContent = showError ? message : "";
+        error.hidden = !showError;
+        container.classList.toggle("field-invalid", showError);
+      }
+
+      function validateField(name) {
+        const { input, validate } = fields[name];
+        const message = validate(input.value);
+        setFieldState(name, message);
+        return message;
+      }
+
+      Object.keys(fields).forEach((name) => {
+        fields[name].input.addEventListener("input", () => {
+          if (submitted) {
+            validateField(name);
+          }
+        });
+      });
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        submitted = true;
+
+        const fieldNames = Object.keys(fields);
+        const results = fieldNames.map((name) => ({ name, message: validateField(name) }));
+        const firstInvalid = results.find((field) => field.message);
+
+        if (firstInvalid) {
+          status.textContent = "Please review the highlighted fields and try again.";
+          status.dataset.state = "error";
+          fields[firstInvalid.name].input.focus();
+          return;
+        }
+
+        status.textContent = "Thanks. Your support request is ready to send.";
+        status.dataset.state = "success";
+        form.reset();
+        Object.keys(fields).forEach((name) => setFieldState(name, ""));
+        submitted = false;
+      });
+    }
+
+    render();
+  </script>
+</body>
+</html>
*** End Patch
