348.     function App() {
349.       return `
350.         <main id="maincontent" class="page-shell" tabindex="-1">
351.           <section class="hero" aria-labelledby="support-heading">
352.             <div>
353.               <div class="eyebrow">Support team</div>
354.               <h1 id="support-heading">Get in touch with product support</h1>
355.               <p>
356.                 Share your details and our team will follow up with setup guidance,
357.                 account help, or product troubleshooting.
358.               </p>
359.               <ul class="hero-points" aria-label="Support benefits">
360.                 <li>
361.                   <span class="point-icon" aria-hidden="true">1</span>
362.                   <div>
363.                     <strong>Fast human follow-up</strong>
364.                     <span>Reach the right team without routing through a generic inbox.</span>
365.                   </div>
366.                 </li>
367.                 <li>
368.                   <span class="point-icon" aria-hidden="true">2</span>
369.                   <div>
370.                     <strong>Clear next steps</strong>
371.                     <span>We use your contact details to coordinate the best response.</span>
372.                   </div>
373.                 </li>
374.               </ul>
375.             </div>
376.             ${ContactForm()}
377.           </section>
378.         </main>
379.       `;
380.     }
381. 
382.     function ContactForm() {
383.       return `
384.         <section class="form-card" aria-labelledby="contact-form-heading">
385.           <h2 id="contact-form-heading">Contact support</h2>
386.           <p>Required fields are marked with an asterisk.</p>
387.           <form id="support-form" class="contact-form" novalidate>
388.             <p class="required-note">Fields marked <span class="required-mark" aria-hidden="true">*</span> are required.</p>
389. 
390.             <div class="form-field" data-field="fullName">
391.               <label for="fullName">Full name <span class="required-mark" aria-hidden="true">*</span></label>
392.               <input
393.                 id="fullName"
394.                 name="fullName"
395.                 type="text"
396.                 autocomplete="name"
397.                 required
398.                 aria-required="true"
399.                 aria-describedby="fullName-error"
400.               >
401.               <p id="fullName-error" class="error-text" hidden></p>
402.             </div>
403. 
404.             <div class="form-field" data-field="email">
405.               <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
406.               <input
407.                 id="email"
408.                 name="email"
409.                 type="email"
410.                 inputmode="email"
411.                 autocomplete="email"
412.                 required
413.                 aria-required="true"
414.                 aria-describedby="email-error"
415.               >
416.               <p id="email-error" class="error-text" hidden></p>
417.             </div>
418. 
419.             <div class="form-field" data-field="phone">
420.               <label for="phone">Phone number</label>
421.               <input
422.                 id="phone"
423.                 name="phone"
424.                 type="tel"
425.                 inputmode="tel"
426.                 autocomplete="tel"
427.                 aria-describedby="phone-help phone-error"
428.               >
429.               <p id="phone-help" class="helper-text">Optional. Use digits only, such as 5551234567, or include spaces, dashes, or a leading + for country code.</p>
430.               <p id="phone-error" class="error-text" hidden></p>
431.             </div>
432. 
433.             <p id="form-status" class="status-text" aria-live="polite"></p>
434.             <button type="submit">Send request</button>
435.           </form>
436.         </section>
437.       `;
438.     }
439. 
440.     function render() {
441.       document.getElementById("app").innerHTML = App();
442.       setupForm();
443.     }
444. 
445.     function setupForm() {
446.       const form = document.getElementById("support-form");
447.       const fields = {
448.         fullName: {
449.           input: document.getElementById("fullName"),
450.           error: document.getElementById("fullName-error"),
451.           validate(value) {
452.             if (!value.trim()) {
453.               return "Error: Enter your full name.";
454.             }
455.             return "";
456.           }
457.         },
458.         email: {
459.           input: document.getElementById("email"),
460.           error: document.getElementById("email-error"),
461.           validate(value) {
462.             if (!value.trim()) {
463.               return "Error: Enter your email address.";
464.             }
465.             if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(value.trim())) {
466.               return "Error: Enter a valid email address, like name@example.com.";
467.             }
468.             return "";
469.           }
470.         },
471.         phone: {
472.           input: document.getElementById("phone"),
473.           error: document.getElementById("phone-error"),
474.           validate(value) {
475.             if (!value.trim()) {
476.               return "";
477.             }
478.             if (!/^\\+?[0-9()\\-\\s]{7,20}$/.test(value.trim())) {
479.               return "Error: Enter a valid phone number using digits and optional spaces, dashes, parentheses, or a leading +.";
480.             }
481.             return "";
482.           }
483.         }
484.       };
485.       const status = document.getElementById("form-status");
486.       let submitted = false;
487. 
488.       function setFieldState(name, message) {
489.         const { input, error } = fields[name];
490.         const container = input.closest(".form-field");
491.         const showError = Boolean(message) && submitted;
492. 
493.         input.setAttribute("aria-invalid", showError ? "true" : "false");
494.         error.textContent = showError ? message : "";
495.         error.hidden = !showError;
496.         container.classList.toggle("field-invalid", showError);
497.       }
498. 
499.       function validateField(name) {
500.         const { input, validate } = fields[name];
501.         const message = validate(input.value);
502.         setFieldState(name, message);
503.         return message;
504.       }
505. 
506.       Object.keys(fields).forEach((name) => {
507.         fields[name].input.addEventListener("input", () => {
508.           if (submitted) {
509.             validateField(name);
510.           }
511.         });
512.       });
513. 
514.       form.addEventListener("submit", (event) => {
515.         event.preventDefault();
516.         submitted = true;
517. 
518.         const fieldNames = Object.keys(fields);
519.         const results = fieldNames.map((name) => ({ name, message: validateField(name) }));
520.         const firstInvalid = results.find((field) => field.message);
521. 
522.         if (firstInvalid) {
523.           status.textContent = "Please review the highlighted fields and try again.";
524.           status.dataset.state = "error";
525.           fields[firstInvalid.name].input.focus();
526.           return;
527.         }
528. 
529.         status.textContent = "Thanks. Your support request is ready to send.";
530.         status.dataset.state = "success";
531.         form.reset();
532.         Object.keys(fields).forEach((name) => setFieldState(name, ""));
533.         submitted = false;
534.       });
535.     }
536. 
537.     render();
538.   </script>
